import json, subprocess, warnings
warnings.filterwarnings("ignore")
from TTS.utils.synthesizer import Synthesizer
from hts_close import close_voice
lines = [
 "बार बार नाक से ब्लड, साइनस की प्रॉब्लम, खांसी में ब्लड, या यूरिन में ब्लड और प्रोटीन? डॉक्टर ए एन सी ए टेस्ट लिख सकते हैं. सी ए एन सी ए और पी ए एन सी ए का मतलब क्या है? आखिर तक देखिए.",
 "ए एन सी ए यानी, एंटी न्यूट्रोफिल साइटोप्लाज़्मिक एंटीबॉडी. ये ऐसी एंटीबॉडी हैं, जो गलती से हमारे व्हाइट ब्लड सेल्स, यानी न्यूट्रोफिल्स के खिलाफ बनती हैं. ये वैस्कुलाइटिस से जुड़ी हैं, यानी ब्लड वेसल्स में सूजन वाली बीमारी.",
 "माइक्रोस्कोप टेस्ट में, दो पैटर्न दिखते हैं. सी ए एन सी ए, जिसमें सेल का साइटोप्लाज़्म चमकता है. यह अक्सर पी आर थ्री एंटीबॉडी होती है. और पी ए एन सी ए, जिसमें न्यूक्लियस के चारों ओर चमक दिखती है. यह अक्सर एम पी ओ एंटीबॉडी होती है.",
 "आजकल डॉक्टर अक्सर, पी आर थ्री और एम पी ओ का अलग अलग टेस्ट करवाते हैं. दो हज़ार सत्रह की इंटरनेशनल गाइडलाइन, इसी को पहला टेस्ट मानती है. माइक्रोस्कोप वाला टेस्ट, ज़रूरत पड़ने पर साथ में किया जाता है.",
 "किस बीमारी से जुड़ा है? पी आर थ्री, यानी सी ए एन सी ए, अक्सर जी पी ए में, जो नाक, फेफड़े और किडनी को प्रभावित कर सकती है. एम पी ओ, यानी पी ए एन सी ए, अक्सर माइक्रोस्कोपिक पॉलीएंजाइटिस, और ई जी पी ए में मिलती है. पी ए एन सी ए, कुछ और बीमारियों, और कुछ मेडिसिन्स में भी आ सकती है.",
 "डॉक्टर यह टेस्ट कब कहते हैं? लंबे समय तक साइनस, नाक में पपड़ी, या नाक से ब्लड. खांसी में ब्लड. यूरिन में ब्लड या प्रोटीन, और बढ़ता क्रिएटिनिन. स्किन पर रैश, हाथ पैर में सुन्नपन, या बिना वजह बुखार और वज़न घटना. अस्थमा के साथ ज़्यादा इओसिनोफिल्स.",
 "रिपोर्ट कैसे समझें? पॉज़िटिव रिपोर्ट अकेले, डायग्नोसिस नहीं है. और नेगेटिव रिपोर्ट भी, वैस्कुलाइटिस को पूरी तरह रूल आउट नहीं करती. डॉक्टर सिम्पटम्स, दूसरे टेस्ट, और कई बार बायोप्सी देखकर फैसला करते हैं.",
 "ज़रूरी बात. किडनी पर असर वाली वैस्कुलाइटिस, जल्दी बढ़ सकती है, इसलिए जल्दी डायग्नोसिस और ट्रीटमेंट ज़रूरी है. सैंपल सिर्फ ब्लड का, खाली पेट की ज़रूरत नहीं. ट्रीटमेंट के दौरान, डॉक्टर यह टेस्ट दोबारा भी करवा सकते हैं.",
 close_voice("क्या आपने कभी ए एन सी ए टेस्ट के बारे में सुना है?"),
]
import os
d = os.environ.get("HTS_MODEL", "/tmp/hi/hi/")
s = Synthesizer(tts_checkpoint=d + "fastpitch/best_model.pth", tts_config_path=d + "fastpitch/config.json",
                vocoder_checkpoint=d + "hifigan/best_model.pth", vocoder_config=d + "hifigan/config.json", use_cuda=False)
durs = []
for i, l in enumerate(lines):
    f = f"/tmp/ancar_{i}.wav"; s.save_wav(s.tts(l, speaker_name="female"), f)
    subprocess.run(["ffmpeg","-nostdin","-y","-loglevel","error","-i",f,"-af","rubberband=pitch=0.96:formant=preserved,equalizer=f=250:t=q:w=1:g=2,treble=g=-1.5:f=6000",f"/tmp/anca_{i}.wav"],check=True); f=f"/tmp/anca_{i}.wav"
    durs.append(float(subprocess.check_output(["ffprobe", "-v", "error", "-show_entries", "format=duration", "-of", "csv=p=0", f]).decode()))
json.dump(durs, open("/tmp/anca_durs.json", "w")); print([round(x, 1) for x in durs], round(sum(durs), 1))
